dg_read_field_def_store_stats_request(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 32 - 7 -> dg_read_field_def_store_stats_request(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
dg_read_field_def_store_stats_request(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_store_stats_request_store_id(Rest, 0, 0, 0, F@_1, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_store_stats_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                1 -> skip_64_store_stats_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                2 -> skip_length_delimited_store_stats_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                3 -> skip_group_store_stats_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                5 -> skip_32_store_stats_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData)
            end
    end;
dg_read_field_def_store_stats_request(<<>>, 0, 0, _, F@_1, _) -> #{store_id => F@_1}.

d_field_store_stats_request_store_id(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_store_stats_request_store_id(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
d_field_store_stats_request_store_id(<<0:1, X:7, Rest/binary>>, N, Acc, F, _, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bytes:Len/binary, Rest2/binary>> = Rest, Bytes2 = binary:copy(Bytes), {id(Bytes2, TrUserData), Rest2} end,
    dfp_read_field_def_store_stats_request(RestF, 0, 0, F, NewFValue, TrUserData).

skip_varint_store_stats_request(<<1:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> skip_varint_store_stats_request(Rest, Z1, Z2, F, F@_1, TrUserData);
skip_varint_store_stats_request(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_store_stats_request(Rest, Z1, Z2, F, F@_1, TrUserData).

skip_length_delimited_store_stats_request(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> skip_length_delimited_store_stats_request(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
