verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        store_stats_request -> v_msg_store_stats_request(Msg, [MsgName], TrUserData);
        store_stats_response -> v_msg_store_stats_response(Msg, [MsgName], TrUserData);
        stream_info_request -> v_msg_stream_info_request(Msg, [MsgName], TrUserData);
        stream_info_response -> v_msg_stream_info_response(Msg, [MsgName], TrUserData);
        event_type_summary_request -> v_msg_event_type_summary_request(Msg, [MsgName], TrUserData);
        event_type_summary_entry -> v_msg_event_type_summary_entry(Msg, [MsgName], TrUserData);
        event_type_summary_response -> v_msg_event_type_summary_response(Msg, [MsgName], TrUserData);
        scavenge_request -> v_msg_scavenge_request(Msg, [MsgName], TrUserData);
        scavenge_response -> v_msg_scavenge_response(Msg, [MsgName], TrUserData);
        scavenge_matching_request -> v_msg_scavenge_matching_request(Msg, [MsgName], TrUserData);
        scavenge_matching_response -> v_msg_scavenge_matching_response(Msg, [MsgName], TrUserData);
        create_link_request -> v_msg_create_link_request(Msg, [MsgName], TrUserData);
        create_link_response -> v_msg_create_link_response(Msg, [MsgName], TrUserData);
        delete_link_request -> v_msg_delete_link_request(Msg, [MsgName], TrUserData);
        delete_link_response -> v_msg_delete_link_response(Msg, [MsgName], TrUserData);
        get_link_request -> v_msg_get_link_request(Msg, [MsgName], TrUserData);
        link_info -> v_msg_link_info(Msg, [MsgName], TrUserData);
        start_link_request -> v_msg_start_link_request(Msg, [MsgName], TrUserData);
        start_link_response -> v_msg_start_link_response(Msg, [MsgName], TrUserData);
        stop_link_request -> v_msg_stop_link_request(Msg, [MsgName], TrUserData);
        stop_link_response -> v_msg_stop_link_response(Msg, [MsgName], TrUserData);
        list_links_request -> v_msg_list_links_request(Msg, [MsgName], TrUserData);
        list_links_response -> v_msg_list_links_response(Msg, [MsgName], TrUserData);
        link_runtime_info -> v_msg_link_runtime_info(Msg, [MsgName], TrUserData);
        reload_catalogue_request -> v_msg_reload_catalogue_request(Msg, [MsgName], TrUserData);
        reload_catalogue_response -> v_msg_reload_catalogue_response(Msg, [MsgName], TrUserData);
        get_catalogue_status_request -> v_msg_get_catalogue_status_request(Msg, [MsgName], TrUserData);
        get_catalogue_status_response -> v_msg_get_catalogue_status_response(Msg, [MsgName], TrUserData);
        cluster_status -> v_msg_cluster_status(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


